//! Loading SpecFrames and TimeFrames from Native dumps reads the
//! Frame-class attributes as C's `astLoadFrame` does, and the observer
//! position under the names older versions of AST wrote.
//!
//! `frame_load_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/frame_load_probe.c`: hand-written descriptions
//! whose per-axis items (`Lbl1`, `Fmt2`, ...) override the Axis objects,
//! which have no axes, or which name a System the class does not know.

use crate::common::native_dump;
// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "frame_load_oracle/cases.rs"]
mod cases;

use ast_core::frames::{Frame, SpecFrame, SpecSystem, TimeFrame, TimeSystem};
use ast_core::{AnyObject, from_native_string};

fn round_trip(f: &dyn Frame, obj: AnyObject) -> Box<dyn Frame> {
    let text = native_dump(&obj).unwrap();
    let back = from_native_string(&text).unwrap();
    let frame = back.as_frame().expect("a Frame");
    assert_eq!(frame.naxes(), f.naxes());
    frame.snapshot()
}

fn set_frame_keys(f: &mut dyn Frame) {
    f.set_digits(10).unwrap();
    f.set_max_axes(3).unwrap();
    f.set_min_axes(1).unwrap();
    f.set_match_end(true).unwrap();
    f.set_permute(false).unwrap();
    f.set_preserve_axes(true).unwrap();
}

fn assert_frame_keys(f: &dyn Frame) {
    assert_eq!(f.digits(), 10);
    assert_eq!((f.test_max_axes(), f.max_axes()), (true, 3));
    assert_eq!((f.test_min_axes(), f.min_axes()), (true, 1));
    assert!(f.test_match_end() && f.match_end());
    assert!(f.test_permute() && !f.permute());
    assert!(f.test_preserve_axes() && f.preserve_axes());
}

/// Digits, MinAxes, MaxAxes, MatchEnd, Permute and PreserveAxes survive a
/// Native round trip of a SpecFrame and a TimeFrame.
#[test]
fn frame_keys_survive_a_round_trip() {
    let mut s = SpecFrame::new(SpecSystem::Freq);
    set_frame_keys(&mut s);
    assert_frame_keys(round_trip(&s, AnyObject::SpecFrame(s.clone())).as_ref());

    let mut t = TimeFrame::new(TimeSystem::Mjd);
    set_frame_keys(&mut t);
    assert_frame_keys(round_trip(&t, AnyObject::TimeFrame(t.clone())).as_ref());
}

/// GeoLat / GeoLon (SpecFrame, specframe.c:7097) and ClLat / ClLon
/// (TimeFrame, timeframe.c:7248) give the observer position when ObsLat and
/// ObsLon are absent.
#[test]
fn legacy_observer_keys_are_read() {
    let spec = "Begin SpecFrame\n Naxes = 1\n Domain = \"SPECTRUM\"\n System = \"FREQ\"\n \
                GeoLat = 0.3\n GeoLon = 1.2\nEnd SpecFrame\n";
    let s = from_native_string(spec).unwrap();
    let s = s.as_frame().unwrap();
    assert_eq!((s.obs_lat(), s.obs_lon()), (0.3, 1.2));

    let time = "Begin TimeFrame\n Naxes = 1\n Domain = \"TIME\"\n System = \"MJD\"\n \
                ClLat = -0.4\n ClLon = 2.5\nEnd TimeFrame\n";
    let t = from_native_string(time).unwrap();
    let t = t.as_frame().unwrap();
    assert_eq!((t.obs_lat(), t.obs_lon()), (-0.4, 2.5));
}

/// One axis as the probe prints it.
fn axis_attrs(f: &dyn Frame, axis: usize) -> cases::Axis {
    (
        (leak(f.label(axis).unwrap()), f.test_label(axis).unwrap()),
        (leak(f.symbol(axis).unwrap()), f.test_symbol(axis).unwrap()),
        (leak(f.unit(axis).unwrap()), f.test_unit(axis).unwrap()),
        (
            leak(f.format_str(axis).unwrap()),
            f.test_format_str(axis).unwrap(),
        ),
        (
            f.axis_digits(axis).unwrap(),
            f.test_axis_digits(axis).unwrap(),
        ),
        (f.direction(axis).unwrap(), f.test_direction(axis).unwrap()),
        (f.top(axis).unwrap(), f.test_top(axis).unwrap()),
        (f.bottom(axis).unwrap(), f.test_bottom(axis).unwrap()),
    )
}

fn leak(s: String) -> &'static str {
    Box::leak(s.into_boxed_str())
}

/// Hand-written descriptions the port loads differently from C, each with
/// what it would take to load it as C does. No shape here is one C's Dump
/// writes. `excluded_descriptions_still_differ` fails when one starts
/// matching.
const FRAME_LOAD_EXCLUDED: &[(&str, &str)] = &[];

fn load_axes(text: &[&str]) -> Result<Vec<cases::Axis>, String> {
    match from_native_string(&text.join("\n")) {
        Ok(obj) => {
            let f = obj.as_frame().expect("a Frame");
            Ok((1..=f.naxes()).map(|i| axis_attrs(f, i)).collect())
        }
        Err(e) if e.code() == ast_core::error::ErrorCode::Attin => Err("Attin".into()),
        Err(e) => Err(format!("{:?}: {e}", e.code())),
    }
}

fn excluded(name: &str) -> bool {
    FRAME_LOAD_EXCLUDED.iter().any(|(n, _)| *n == name)
}

#[test]
fn hand_written_descriptions_load_as_the_c_library_does() {
    let mut failures = Vec::new();
    for &(name, text, want) in cases::CASES.iter().filter(|c| !excluded(c.0)) {
        let got = load_axes(text);
        let want = want.map(<[cases::Axis]>::to_vec).map_err(str::to_string);
        if got != want {
            failures.push(format!("{name}: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Every `FRAME_LOAD_EXCLUDED` entry names a case that still differs from C.
#[test]
fn excluded_descriptions_still_differ() {
    for (name, why) in FRAME_LOAD_EXCLUDED {
        let &(_, text, want) = cases::CASES
            .iter()
            .find(|c| c.0 == *name)
            .unwrap_or_else(|| panic!("{name} is excluded but not a case"));
        let want = want.map(<[cases::Axis]>::to_vec).map_err(str::to_string);
        assert_ne!(
            load_axes(text),
            want,
            "{name} now loads as C does; remove it from FRAME_LOAD_EXCLUDED ({why})"
        );
    }
}
